  "code": "def needs_retake(score: int) -> bool:
    """
    쪽지 시험 재응시 대상인지 판단하는 함수입니다.

    Args:
        score (int): 0 부터 100 까지의 점수

    Returns:
        bool: 20 점보다 높고 60 점보다 낮으면 True (재응시 대상), 그 외는 False
    """
    if score < 20:
        return False
    elif score <= 60:
        return True
    else:
        return False
"}
